// 通常走査で進んだ先を受け取り、循環を検出する。
struct ChainCycleCheck {
    const Node* checkpoint;
    std::size_t power = 1;
    std::size_t distance = 0;

    explicit ChainCycleCheck(const Node* head) noexcept : checkpoint(head) {}

