}
#endif

#ifndef SIRKIT_CHAIN_TAIL_DEFINED
#define SIRKIT_CHAIN_TAIL_DEFINED
inline std::shared_ptr<Node> chain_tail(const std::shared_ptr<Node>& head) {
    const std::shared_ptr<Node>* link = &head;
