    return result;
}
#endif

#ifndef SIRKIT_CYCLE_ENTRY_DEFINED
#define SIRKIT_CYCLE_ENTRY_DEFINED
inline Node* cycle_entry(const std::shared_ptr<Node>& head) noexcept {
    Node* slow = head.get();
