}
#endif

#ifndef SIRKIT_BREAK_CYCLE_DEFINED
#define SIRKIT_BREAK_CYCLE_DEFINED
inline bool break_cycle(const std::shared_ptr<Node>& head) noexcept {
    Node* slow = head.get();
    Node* fast = slow;
    do {
        if (fast == nullptr || !fast->n) return false;
        slow = slow->n.get();
        fast = fast->n->n.get();
