 if(argc!=4)return 2;const std::size_t n=std::strtoull(argv[1],nullptr,0),reps=std::strtoull(argv[2],nullptr,0);const bool shuffled=std::atoi(argv[3]);
 std::vector<std::shared_ptr<Node>>nodes(n);for(auto&node:nodes)node=make_node();std::vector<std::size_t>order(n);std::iota(order.begin(),order.end(),0);if(shuffled){std::mt19937 rng(80395683);std::shuffle(order.begin(),order.end(),rng);}for(std::size_t i=1;i<n;++i)nodes[order[i-1]]->n=nodes[order[i]];
 const std::shared_ptr<Node>head=n?nodes[order[0]]:nullptr;using F=std::size_t(*)(const std::shared_ptr<Node>&);const std::array<F,3>functions={chain_size,chain_size,chain_size_unroll2};std::mt19937 rng(80395683);std::cout<<std::setprecision(17);
 for(int round=0;round<11;++round){std::array<int,3>variants={0,1,2};std::shuffle(variants.begin(),variants.end(),rng);for(int v:variants){F f=functions[v];std::uint64_t sum=0;const auto begin=std::chrono::steady_clock::now();for(std::size_t i=0;i<reps;++i){std::atomic_signal_fence(std::memory_order_seq_cst);sum+=f(head);}const auto end=std::chrono::steady_clock::now();if(sum!=n*reps)return 3;std::cout<<round<<' '<<v<<' '<<std::chrono::duration<double,std::nano>(end-begin).count()<<' '<<sum<<'\n';}}
