#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
using Clock = std::chrono::steady_clock;
static std::size_t observe(const std::shared_ptr<Node>& head) {
    asm volatile("" : : "r"(head.get()) : "memory");
    std::size_t count = 0;
    for (auto p = head.get(); p; p = p->n.get()) ++count;
    return count;
}
int main(int argc, char** argv) {
    if (argc != 5) return 2;
    const std::string op = argv[1];
    const auto n = static_cast<std::size_t>(std::strtoull(argv[2], nullptr, 0));
    const int reps = std::atoi(argv[3]);
    const bool shared = std::atoi(argv[4]) != 0;
    double ns = 0;
    std::uint64_t sum = 0;
    for (int rep = 0; rep < reps; ++rep) {
        std::shared_ptr<Node> head;
        std::vector<std::shared_ptr<Node>> refs;
        if (op == "make") {
            std::vector<std::shared_ptr<Node>> nodes(n);
            auto tail = shared ? make_chain(2) : std::shared_ptr<Node>{};
            const auto begin = Clock::now();
            for (auto& p : nodes) p = make_node(tail);
            asm volatile("" : : "r"(nodes.data()) : "memory");
            const auto end = Clock::now();
            ns += std::chrono::duration<double, std::nano>(end - begin).count();
            for (auto& p : nodes) {
                if (!p || p->n != tail) return 3;
                sum += observe(p);
            }
        } else if (op == "make_chain") {
            auto tail = shared ? make_chain(2) : std::shared_ptr<Node>{};
            const auto begin = Clock::now();
            head = make_chain(n, tail);
            asm volatile("" : : "r"(head.get()) : "memory");
            const auto end = Clock::now();
            ns += std::chrono::duration<double, std::nano>(end - begin).count();
            sum += observe(head);
        } else if (op == "push") {
            if (shared) refs.reserve(n);
            const auto begin = Clock::now();
            for (std::size_t i = 0; i < n; ++i) {
                if (shared) refs.push_back(head);
                push_front_node(head);
            }
            asm volatile("" : : "r"(head.get()) : "memory");
            const auto end = Clock::now();
            ns += std::chrono::duration<double, std::nano>(end - begin).count();
            sum += observe(head);
        } else {
            head = make_chain(n);
            sum += observe(head);
            if (shared) {
                refs.reserve(n);
                for (auto p = head; p; p = p->n) refs.push_back(p);
            }
            if (op == "pop") {
                const auto begin = Clock::now();
                for (std::size_t i = 0; i < n; ++i) sum += pop_front_node(head);
                const auto end = Clock::now();
                ns += std::chrono::duration<double, std::nano>(end - begin).count();
                sum += !head;
            } else if (op == "clone") {
                const auto begin = Clock::now();
                auto copy = clone_chain(head);
                asm volatile("" : : "r"(copy.get()) : "memory");
                const auto end = Clock::now();
                ns += std::chrono::duration<double, std::nano>(end - begin).count();
                sum += observe(copy);
            } else if (op == "clear") {
                std::weak_ptr<Node> weak = head;
                const auto begin = Clock::now();
                clear_chain(head);
                const auto end = Clock::now();
                ns += std::chrono::duration<double, std::nano>(end - begin).count();
                sum += weak.expired();
            } else return 4;
        }
    }
    std::cout << std::setprecision(17) << ns << ' ' << sum << '\n';
}

