#include HEADER
#include <cstddef>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <new>
#include <type_traits>
#include <utility>
namespace {
volatile int budget = -1;
volatile std::size_t allocations = 0;
volatile std::size_t live = 0;
volatile std::size_t last_bytes = 0;
}
[[gnu::noinline]] void* operator new(std::size_t bytes) {
    if (budget == 0) throw std::bad_alloc();
    if (budget > 0) budget = budget - 1;
    if (void* p = std::malloc(bytes ? bytes : 1)) {
        allocations = allocations + 1;
        live = live + 1;
        last_bytes = bytes;
        return p;
    }
    throw std::bad_alloc();
}
[[gnu::noinline]] void* operator new[](std::size_t bytes) { return ::operator new(bytes); }
[[gnu::noinline]] static void release(void* p) noexcept {
    if (p) live = live - 1;
    std::free(p);
}
void operator delete(void* p) noexcept { release(p); }
void operator delete[](void* p) noexcept { release(p); }
void operator delete(void* p, std::size_t) noexcept { release(p); }
void operator delete[](void* p, std::size_t) noexcept { release(p); }
static void check(bool ok) { if (!ok) std::abort(); }
[[gnu::noinline]] std::shared_ptr<Node> factory_probe(std::shared_ptr<Node> next) {
    return make_node(std::move(next));
}
int main() {
    static_assert(std::is_nothrow_default_constructible_v<Node>);
    static_assert(std::is_nothrow_constructible_v<Node, std::shared_ptr<Node>>);
    static_assert(std::is_nothrow_destructible_v<Node>);
    static_assert(!noexcept(make_node()));
    const auto live_before = live;
    std::size_t bytes = 0;
    {
        const auto old = allocations;
        auto node = factory_probe({});
        check(allocations == old + 1);
        bytes = last_bytes;
        check(node && !node->n && node->n.use_count() == 0 && node.use_count() == 1);
    }
    check(live == live_before);
    {
        auto tail = make_chain(3);
        auto observer = tail;
        const auto before = allocations;
        auto node = factory_probe(tail);
        check(allocations == before + 1 && node->n == tail && tail.use_count() == 3);
        const auto owner_count = tail.use_count();
        const auto old_live = live;
        budget = 0;
        bool threw = false;
        try { (void)make_node(tail); } catch (const std::bad_alloc&) { threw = true; }
        budget = -1;
        check(threw && live == old_live && tail == observer && tail.use_count() == owner_count);
        auto moved = make_node(std::move(tail));
        check(!tail && moved->n == observer);
    }
    check(live == live_before);
    {
        int deleted = 0;
        {
            auto null_owner = std::shared_ptr<Node>(nullptr, [&deleted](Node* p) {
                check(p == nullptr);
                ++deleted;
            });
            auto node = make_node(null_owner);
            check(!node->n && node->n.use_count() == 2 && null_owner.use_count() == 2);
            null_owner.reset();
            check(!node->n && node->n.use_count() == 1);
        }
        check(deleted == 1);
    }
    check(live == live_before);
    std::cout << "PASS Node_size=" << sizeof(Node) << " Node_align=" << alignof(Node)
              << " shared_size=" << sizeof(std::shared_ptr<Node>)
              << " control_allocation_bytes=" << bytes << " live_delta=0\n";
}

